import{z as p,x as n,o as t,c as d,q as r,j as E,D as e,d as i,s,S as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"掩模数据准备 MDP","description":"","frontmatter":{"title":"掩模数据准备 MDP","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mask-data-prep.md","filePath":"litho/mask-data-prep.md","lastUpdated":1791413859000}'),P={name:"litho/mask-data-prep.md"};function A(m,a,D,B,h,C){const o=n("Mermaid");return t(),d("div",null,[a[2]||(a[2]=r('<h1 id="掩模数据准备-mdp" tabindex="-1">掩模数据准备 MDP <a class="header-anchor" href="#掩模数据准备-mdp" aria-label="Permalink to &quot;掩模数据准备 MDP&quot;">​</a></h1><div class="epigraph"><p>MDP 不是「把 GDS 拷到写模机」：它是作业单、分割、剂量图和机台坐标的合同，错一格就写错一场。</p><footer>—— 对照 SPIE Photomask / BACUS 对 mask data preparation 的产线叙述</footer></div><p><a href="/litho/layout-layers-flow">上一课</a>把设计层收成一张张派生明暗图。缺口是这张图还不能曝光：写模机要的是带剂量、带场拼接、带对准的作业。本课钉 MDP（mask data preparation）。矩形怎么切，留给<a href="/litho/fracturing">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>掩模厂同时接许多客户、许多机台家族（VSB 与 <a href="/litho/multibeam-mask-writer">多束</a>）、许多膜系。MDP 的问题是把「客户多边形 + 技术文件」变成「这一台写模机今晚能跑的作业」：坐标系（版中心、扫描机对准键）、放大率（常见 \\(4\\times\\)）、镜面翻转、芯片阵列、剂量基准、PEC 与 MPC 的版本号。缺任何一项，写出的版在扫描机上会对不准或 CD 整张偏。</p><p>缺口是<strong>作业语义</strong>，不是再列一层布尔。把 MDP 理解成压缩文件，会漏掉：同一 OASIS 在不同 jobdeck 下可以写出镜像或错位的场。</p><h3 id="客户-opc-与版厂-mdp-的分界" tabindex="-1">客户 OPC 与版厂 MDP 的分界 <a class="header-anchor" href="#客户-opc-与版厂-mdp-的分界" aria-label="Permalink to &quot;客户 OPC 与版厂 MDP 的分界&quot;">​</a></h3><p>OPC/ILT 在晶圆坐标系里修边，目标是硅上轮廓。MDP 在掩模坐标系里准备可写数据，目标是版上吸收体。两者通过放大率与色调衔接。合同必须写清：谁做 MPC、谁做 PEC、残差算谁的 mask CDU。把版厂 MDP 叫做「第二次 OPC」，会与晶圆模型抢名。</p><p><span class="marginnote">作业单（jobdeck）是 MDP 的一部分。只交「一层 OASIS」而不交阵列、剂量与机台号，等于让版厂猜曝光场怎么铺。</span></p><p><span class="marginnote">术语翻译：jobdeck 就是一份「排产脚本」——告诉写模机这块版上铺几个芯片阵列、每个摆在哪个坐标、用哪个对准键、基准剂量多少。缺了它，OASIS 文件只是散装几何，写模机不知道要写到哪里、按什么方向写。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>通称链条：输入检查（网格、自交、层完整性）→ 坐标变换与阵列 → 按机台做 fracturing / 栅格化 → PEC 剂量 → MPC 几何或剂量微调 → 输出写模格式与检验参考。每一步留校验和，以便 <a href="/litho/mask-inspection-d2d-d2db">die-to-database</a> 知道比对的是哪一跳。</p>',12)),(t(),E(l,null,{default:e(()=>[s(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20W%5B%22%E6%99%B6%E5%9C%86%E5%9D%90%E6%A0%87%20OPC%20%2F%20ILT%20%E4%BF%AE%E8%BE%B9%22%5D%20--%3E%20S%5B%22%E4%B9%98%E6%94%BE%E5%A4%A7%E7%8E%87%E5%B8%B8%E4%B8%BA%204%20%E5%80%8D%22%5D%0A%20%20S%20--%3E%20F%5B%22%E9%95%9C%E5%83%8F%E7%BF%BB%E8%BD%AC%E7%BA%A6%E5%AE%9A%22%5D%0A%20%20F%20--%3E%20M%5B%22%E6%8E%A9%E6%A8%A1%E5%9D%90%E6%A0%87%20MDP%22%5D%0A%20%20M%20--%3E%20T%5B%22%E7%89%88%E4%B8%8A%E5%90%B8%E6%94%B6%E4%BD%93%E7%9B%AE%E6%A0%87%22%5D%0A%20%20C%5B%22%E5%90%88%E5%90%8C%3A%20%E8%B0%81%E5%81%9A%20MPC%20%2F%20PEC%20%E6%AE%8B%E5%B7%AE%E5%BD%92%E8%B0%81%22%5D%20--%3E%20T%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">这张图回答的问题是：客户 OPC 与版厂 MDP 怎么在两个坐标系之间交接。晶圆坐标里修的边，要经过放大、翻转两道约定才变成掩模坐标里的可写数据；交接处必须靠合同写清归属，否则残差没人认账。</span></p><p><span class="marginnote">常见误区：初学者容易把 MDP 当成「转个文件格式」。实际上同一份几何，换一套 jobdeck 或镜像约定，写出来的版可能整体镜像或错位——错一格就写错一场，这也是链条上每步都留校验和的原因。</span></p><p>与高 NA 经济课的衔接：曲线层与碎助条让 MDP 墙钟和磁盘成为 TAPOUT 关键路径，不是只在写束上付钱。GPU 加速的是 OPC；MDP 的带宽与规则检查是另一条产能。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>放大率把晶圆纳米变成版上四倍几何（anamorphic 高 NA 则 x/y 不同，见 <a href="/litho/anamorphic-mask-mag">变形放大</a>）。MDP 必须按扫描机列的放大写入，不能一律 \\(4\\times\\)。翻转来自光路折转：透射 DUV 与反射 EUV 的「客户看到的芯片方向」对版厂是不同的镜像约定。</p><p><span class="marginnote">直觉类比：可以把它想象成洗照片——底片上的图案是照片的四倍大，方向还可能是反的，因为光路会折转、镜头会缩小。版厂要按「洗出来正好」来准备底片，而不是按照片本身的样子画。</span></p><p>剂量基准把「设计里的 1/0」变成写模机的驻留时间。PEC 在此之上再按密度调制。没有 MDP 把基准锁死，后课的写入时间公式没有分母。</p>',7)),(t(),E(l,null,{default:e(()=>[s(o,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAY%5B%22%E6%B4%BE%E7%94%9F%E6%8E%A9%E6%A8%A1%E5%B1%82%22%5D%20--%3E%20JOB%5B%22%E4%BD%9C%E4%B8%9A%E5%8D%95%3A%20%E5%9D%90%E6%A0%87%20%E9%98%B5%E5%88%97%20%E5%89%82%E9%87%8F%22%5D%0A%20%20JOB%20--%3E%20FRAC%5B%22%E5%88%86%E5%89%B2%20%2F%20%E6%A0%85%E6%A0%BC%22%5D%0A%20%20FRAC%20--%3E%20PEC%5B%22PEC%22%5D%0A%20%20PEC%20--%3E%20MPC%5B%22MPC%22%5D%0A%20%20MPC%20--%3E%20WRITE%5B%22%E5%86%99%E6%A8%A1%E6%A0%BC%E5%BC%8F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>MDP 不修复空白片缺陷，不替代 AIMS。它只保证数据与机台合同一致。专有写模格式若不能回放成几何，客户无法独立核对——这是 TAPOUT 风险，不是格式先进。</p><p>后课默认：作业语义已定；下一跳是如何把多边形切成 VSB 炮或等价片段。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MDP 把派生层变成带坐标、剂量与机台版本的可写作业。</li><li>OPC 修晶圆边；MDP 准备版上数据。二者通过放大率与色调衔接。</li><li>anamorphic 场不能一律按 \\(4\\times\\) 变换。</li><li>出处：SPIE Photomask 对 MDP 与 jobdeck 的产线论述；SEMI 掩模数据惯例。</li></ul>',5))])}const M=p(P,[["render",A]]);export{_ as __pageData,M as default};
